query PreflightFacts($owner: String!, $name: String!, $number: Int!, $branchQuery: String!) {
  viewer { login }
  repository(owner: $owner, name: $name) {
    id
    nameWithOwner
    visibility
    owner { login }
    defaultBranchRef { name }
    labels(first: 100) {
      pageInfo { hasNextPage hasPreviousPage }
      nodes { id name }
    }
    issueOrPullRequest(number: $number) {
      __typename
      ... on Issue {
        ...issueFacts
        parent { ...issueFacts }
        subIssues(first: 100) {
          pageInfo { hasNextPage hasPreviousPage }
          nodes { ...issueFacts }
        }
        projectItems(first: 20) { totalCount }
        comments(first: 100) {
          pageInfo { hasNextPage hasPreviousPage }
          nodes { id databaseId author { login } authorAssociation viewerDidAuthor body }
        }
      }
    }
    refs(refPrefix: "refs/heads/", query: $branchQuery, first: 20) {
      pageInfo { hasNextPage hasPreviousPage }
      nodes {
        name
        associatedPullRequests(states: [OPEN], first: 10) {
          pageInfo { hasNextPage hasPreviousPage }
          nodes { number author { login } authorAssociation viewerDidAuthor baseRepository { nameWithOwner } }
        }
      }
    }
  }
}

fragment issueFacts on Issue {
  id
  number
  title
  state
  author { login }
  authorAssociation
  viewerDidAuthor
  repository { nameWithOwner visibility owner { login } }
  userContentEdits(first: 100) {
    pageInfo { hasNextPage hasPreviousPage }
    nodes { editor { login } }
  }
  timelineItems(first: 100, itemTypes: [RENAMED_TITLE_EVENT]) {
    pageInfo { hasNextPage hasPreviousPage }
    nodes { ... on RenamedTitleEvent { actor { login } } }
  }
}
